from fractions import Fraction

def posterior_positive(prior, sensitivity, false_positive):
    for value in (prior, sensitivity, false_positive):
        if type(value) is not Fraction or not 0 <= value <= 1:
            raise ValueError("expected Fraction probability in [0,1]")
    true_positive_mass = prior * sensitivity
    positive_mass = true_positive_mass + (1 - prior) * false_positive
    if positive_mass == 0:
        raise ValueError("conditioning event has zero probability")
    return true_positive_mass / positive_mass

print(posterior_positive(Fraction(1,100), Fraction(9,10), Fraction(1,20)))
print(posterior_positive(Fraction(1,2), Fraction(9,10), Fraction(1,20)))
try:
    posterior_positive(Fraction(1,2), Fraction(0), Fraction(0))
except ValueError:
    print("undefined conditional")
